test('sync watcher should not be batched', () => {
  const a = ref(0)
  const b = ref(0)
  let pauseB = false
  watch(
    a,
    () => {
      pauseB = true
      b.value = a.value + 1
      pauseB = false
    },
    { flush: 'sync' },
  )
  watch(
    b,
    () => {
      if (!pauseB) {
        throw new Error('should not be called')
      }
    },
    { flush: 'sync' },
  )

  a.value = 1
  expect(b.value).toBe(2)
})

test('watchEffect should not fire on computed deps that did not change', async () => {
  const a = ref(0)
  const c = computed(() => a.value % 2)
  const spy = vi.fn()
  watchEffect(() => {
    spy()
    c.value
  })
  expect(spy).toHaveBeenCalledTimes(1)
  a.value += 2
  await nextTick()
  expect(spy).toHaveBeenCalledTimes(1)
})

test('circular reference', async () => {
  const obj = { a: 1 }
  // @ts-expect-error
  obj.b = obj
  const foo = ref(obj)
  const spy = vi.fn()

  watch(foo, spy, { deep: true })

  // @ts-expect-error
  foo.value.b.a = 2
  await nextTick()
  expect(spy).toHaveBeenCalledTimes(1)
  expect(foo.value.a).toBe(2)
})

